#include "neural_chip/FullDiveChipFrameDiff.h"
#include <cassert>
#include <string>
static bool has(const std::vector<dnxr::FrameFieldDelta>& d,const char* p){ for(const auto& x:d) if(std::string(x.fieldPath)==p) return true; return false; }
int main(){ dnxr::FullDiveChipFrame a,b; b.visual.depthFar01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"visual.depthFar01")); b=a; b.auditory.envelopeAttack01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"auditory.envelopeAttack01")); b=a; b.touch.slip01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"touch.slip01")); b=a; b.proprioception.rightArmPose01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"proprioception.rightArmPose01")); b=a; b.vestibular.gravityDirection01=0.7f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"vestibular.gravityDirection01")); b=a; b.motorIntent.leftHandGrip01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"motorIntent.leftHandGrip01")); b=a; b.olfactory.smokeWarning01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"olfactory.smokeWarning01")); b=a; b.gustatory.umami01=0.2f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"gustatory.umami01")); b=a; b.realityAnchor.orientation01=0.8f; assert(has(dnxr::FullDiveChipFrameDiff::compare(a,b),"realityAnchor.orientation01")); }
